contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes calldata encodedParameters, address ownedBy) public {
        // Try to make create() succeed: attempt owner-gated setup calls (they revert,
        // since this contract is not the owner) and then call create() directly.
        bool setupImplReverted;
        c.updateRoundImplementation(payable(address(1))); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setupImplReverted = true; } else { setupImplReverted = false; }

        bool setupSettingsReverted;
        c.updateAlloSettings(address(1)); bool __rev1 = __ESBMC_reverted(); if (__rev1) { setupSettingsReverted = true; } else { setupSettingsReverted = false; }

        bool createReverted;
        c.create(encodedParameters, ownedBy); bool __rev2 = __ESBMC_reverted(); if (__rev2) { createReverted = true; } else { createReverted = false; }

        assert(setupImplReverted && setupSettingsReverted && createReverted);
    }
    receive() external payable {}
}

